import{_ as e,o as t,c as o,a2 as r}from"./chunks/framework.CfwCq2QB.js";const n="/dev-go-docs/shots/0.2.3/zh-CN/light/popup-function.png",s="/dev-go-docs/shots/0.2.3/zh-CN/light/options-enhance.png",_=JSON.parse('{"title":"网页增强","description":"","frontmatter":{},"headers":[],"relativePath":"features/page-enhance.md","filePath":"features/page-enhance.md"}'),i={name:"features/page-enhance.md"};function h(c,a,p,l,d,m){return t(),o("div",null,[...a[0]||(a[0]=[r('<h1 id="网页增强" tabindex="-1">网页增强 <a class="header-anchor" href="#网页增强" aria-label="Permalink to &quot;网页增强&quot;">​</a></h1><p>一句话：按站点解除复制 / 选择 / 右键限制，管理悬浮快捷栏在各网站的显示，都能在弹窗「功能」页对当前网站一键开关。</p><p>弹窗「功能」页是这三个开关的统一入口，每个开关只影响当前网站，旁边会显示当前状态（如「已在 github.com 停用」「共 3 个站点已开启」）。</p><img src="'+n+'" alt="弹窗功能页" style="width:60%;display:block;margin-left:auto;margin-right:auto;"><p><em>图：弹窗「功能」页——三个按站开关显示当前网站状态。</em></p><h2 id="划词工具条" tabindex="-1">划词工具条 <a class="header-anchor" href="#划词工具条" aria-label="Permalink to &quot;划词工具条&quot;">​</a></h2><p>对当前网站显示 / 停用划词工具条。在线编辑器、本身就带划词功能的网站上容易误触，在这里关掉，其他网站照常使用。停用列表在设置页「划词 → 停用划词的网站」管理。详见<a href="/dev-go-docs/features/selection-toolbar.html">划词工具条</a>。</p><h2 id="悬浮快捷栏" tabindex="-1">悬浮快捷栏 <a class="header-anchor" href="#悬浮快捷栏" aria-label="Permalink to &quot;悬浮快捷栏&quot;">​</a></h2><p>对当前网站显示 / 隐藏悬浮快捷栏；设置页「网页增强」里还有总开关和「不显示的网站」列表。详见<a href="/dev-go-docs/features/dock.html">悬浮快捷栏</a>。</p><h2 id="解除本站复制限制" tabindex="-1">解除本站复制限制 <a class="header-anchor" href="#解除本站复制限制" aria-label="Permalink to &quot;解除本站复制限制&quot;">​</a></h2><p>有些网站禁止复制、选择文字、右键（复制不了文档内容、看不到右键菜单）。开启后放开当前网站的这三类限制。</p><p><strong>为什么是按站点而不是全局</strong>：全局放开会破坏在线编辑器等网站的正常行为，所以只对你加进列表的网站生效。需要哪个站开哪个：弹窗「功能」页一键开关，或在设置页「网页增强 → 解除复制限制的网站」里添加（每行一个域名，如 <code>www.example.com</code>）。</p><h2 id="其他" tabindex="-1">其他 <a class="header-anchor" href="#其他" aria-label="Permalink to &quot;其他&quot;">​</a></h2><p>弹窗「功能」页还有 AI 助手和网页工具（WebMCP）的快捷入口，见对应功能页；页面底部的「管理全部网站与更多功能」直达设置页。</p><img src="'+s+'" alt="网页增强设置"><p><em>图：设置页「网页增强」——悬浮快捷栏总开关与解除复制限制的网站列表。</em></p>',16)])])}const f=e(i,[["render",h]]);export{_ as __pageData,f as default};
